"""Tests for tasks_api.models."""

from __future__ import annotations

from datetime import datetime, timedelta, timezone

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus


# ── TaskStatus / TaskPriority enums ──────────────────────────────────

class TestTaskStatus:
    def test_values(self):
        assert TaskStatus.PENDING.value == "pending"
        assert TaskStatus.DONE.value == "done"

    def test_string_equality(self):
        assert TaskStatus.PENDING == "pending"


class TestTaskPriority:
    def test_values(self):
        assert TaskPriority.LOW.value == "low"
        assert TaskPriority.MEDIUM.value == "medium"
        assert TaskPriority.HIGH.value == "high"

    def test_order_key(self):
        assert TaskPriority.order_key(TaskPriority.HIGH) < TaskPriority.order_key(TaskPriority.MEDIUM)
        assert TaskPriority.order_key(TaskPriority.MEDIUM) < TaskPriority.order_key(TaskPriority.LOW)


# ── Tag ──────────────────────────────────────────────────────────────

class TestTag:
    def test_normalization(self):
        assert Tag("  Shopping ").name == "shopping"

    def test_empty_name_rejected(self):
        with pytest.raises(ValueError, match="must not be empty"):
            Tag("   ")

    def test_non_string_rejected(self):
        with pytest.raises(TypeError, match="must be a string"):
            Tag(123)  # type: ignore[arg-type]

    def test_too_long_rejected(self):
        with pytest.raises(ValueError, match="32 characters"):
            Tag("a" * 33)

    def test_illegal_character_rejected(self):
        with pytest.raises(ValueError, match="illegal character"):
            Tag("no spaces")

    def test_allows_hyphens_underscores_digits(self):
        t = Tag("my-tag_42")
        assert t.name == "my-tag_42"


# ── Task.is_overdue ─────────────────────────────────────────────────

class TestTaskIsOverdue:
    def _make(self, *, status=TaskStatus.PENDING, due_at=None):
        return Task(id=1, title="t", status=status, due_at=due_at,
                    created_at=datetime(2026, 1, 1, tzinfo=timezone.utc))

    def test_overdue_when_past_and_pending(self):
        now = datetime(2026, 7, 1, tzinfo=timezone.utc)
        t = self._make(due_at=now - timedelta(days=1))
        assert t.is_overdue(now) is True

    def test_not_overdue_when_done(self):
        now = datetime(2026, 7, 1, tzinfo=timezone.utc)
        t = self._make(status=TaskStatus.DONE, due_at=now - timedelta(days=1))
        assert t.is_overdue(now) is False

    def test_not_overdue_when_no_due_date(self):
        now = datetime(2026, 7, 1, tzinfo=timezone.utc)
        t = self._make(due_at=None)
        assert t.is_overdue(now) is False

    def test_not_overdue_when_future(self):
        now = datetime(2026, 7, 1, tzinfo=timezone.utc)
        t = self._make(due_at=now + timedelta(days=1))
        assert t.is_overdue(now) is False
